// Bind JS runtime: support for the native HTML/JS frontend generated by bindc (split mode).
//
// Copied verbatim into generated `web/` folders as `bind-runtime.js`. A native ES2022 module:
// no npm, no bundler, no build step. It never parses or evaluates strings as HTML or code: UI
// is built with createElement / createTextNode / setAttribute / appendChild only.
//
// Its observable behaviour (numbers, decimals, HTML, page and error markup, link sanitizing,
// screen texts) equals the Rust runtime (runtime/bind-runtime/src/lib.rs) byte for byte; the
// shared vectors in runtime/vectors/ and runtime/bind-runtime-js/tests/*.json check it.
//
// Value representation (see the 3c spec, section 2):
//   Int -> BigInt; Double -> number; Float -> number rounded with f32() after each operation;
//   Boolean -> boolean; String and other text types -> canonical string; T? -> null or the value
//   ({some: v} only when T is itself optional); records -> frozen null-prototype objects
//   (record()); sealed/enum -> frozen {tag, ...fields} (variant()); Result -> variant("Ok" |
//   "Err", [["value", v]]); List<T> -> frozen array; Decimal/Money -> Decimal; functions ->
//   async (ctx, ...args) => ...

/** Maximum nesting of Bind function / lambda entries before RecursionLimit (as in Rust). */
export const MAX_DEPTH = 10000;

/** The screen texts; the same values as the Rust runtime's constants. */
export const TEXTS = Object.freeze({
  loading: "Loading…", // TEXT_LOADING
  requestFailed: "Request failed", // TEXT_REQUEST_FAILED
  titleBadRequest: "Bad request", // TITLE_BAD_REQUEST
  titleNotFound: "Page not found", // TITLE_NOT_FOUND
  titleError: "Something went wrong", // TITLE_ERROR
});

/**
 * A Bind runtime error. `kind` is "RecursionLimit" | "Overflow" | "Remote" | "BadParameter".
 * Remote: `message` is the server's public message, or TEXTS.requestFailed. BadParameter:
 * `message` is the parameter name. Any other exception reaching the boot code is a compiler bug.
 */
export class BindError extends Error {
  constructor(kind, message) {
    super(message);
    this.name = "BindError";
    this.kind = kind;
  }
}

/** Thrown by decoders on malformed data; rpc and readParams turn it into a BindError. */
export class DecodeError extends Error {
  constructor(message) {
    super(message);
    this.name = "DecodeError";
  }
}

// ---------------------------------------------------------------------------------------------
// Call context and recursion limit
// ---------------------------------------------------------------------------------------------

/** The root call context (depth 0). */
export function newCtx() {
  return Object.freeze({ depth: 0 });
}

/**
 * Context for a Bind function or lambda entry: depth + 1, or RecursionLimit past MAX_DEPTH.
 * Always awaits, so each level resumes in a microtask and deep recursion never grows the JS
 * stack. Generated functions start with `ctx = await enter(ctx);`. Builtins do not call it.
 */
export async function enter(ctx) {
  await undefined;
  if (ctx.depth >= MAX_DEPTH) {
    throw new BindError("RecursionLimit", "recursion limit exceeded");
  }
  return Object.freeze({ depth: ctx.depth + 1 });
}

// ---------------------------------------------------------------------------------------------
// Int (BigInt)
// ---------------------------------------------------------------------------------------------

/** Longest accepted Int text, in digits (the optional "-" not counted), as in Rust. */
const MAX_INT_DIGITS = 1000;
const CANONICAL_INT = /^(?:0|-?[1-9][0-9]*)$/;

/** The BigInt of a canonical Int text (`-?[0-9]+`, no leading zeros, no "-0", <= 1000 digits), or null. */
export function intParse(text) {
  if (typeof text !== "string" || !CANONICAL_INT.test(text)) return null;
  const digits = text.startsWith("-") ? text.length - 1 : text.length;
  if (digits > MAX_INT_DIGITS) return null;
  return BigInt(text);
}

export function intToString(n) {
  return n.toString();
}

/** Division truncating toward zero; null when the divisor is zero. */
export function intDiv(a, b) {
  return b === 0n ? null : a / b;
}

/** Remainder with the sign of the dividend; null when the divisor is zero. */
export function intRem(a, b) {
  return b === 0n ? null : a % b;
}

// ---------------------------------------------------------------------------------------------
// Decimal: rust_decimal semantics (96-bit mantissa, scale 0..=28, sign flag kept on zero)
// ---------------------------------------------------------------------------------------------

const MANTISSA_LIMIT = 1n << 96n; // mantissa < 2^96
const MAX_SCALE = 28;
const CANONICAL_DECIMAL = /^(-?)(0|[1-9][0-9]*)(?:\.([0-9]+))?$/;
const POW10 = [];
for (let i = 0n, p = 1n; i <= 58n; i++, p *= 10n) POW10.push(p);

/**
 * A rust_decimal `Decimal`: sign flag, mantissa (BigInt, 0 <= m < 2^96) and scale (0..=28).
 * Not reduced: "1.50" keeps scale 2, like rust_decimal's Display. The sign flag is separate so
 * a negative zero prints "-0" / "-0.00" exactly as rust_decimal does. Instances are frozen.
 */
export class Decimal {
  constructor(negative, mantissa, scale) {
    if (
      typeof negative !== "boolean" ||
      typeof mantissa !== "bigint" ||
      mantissa < 0n ||
      mantissa >= MANTISSA_LIMIT ||
      !Number.isInteger(scale) ||
      scale < 0 ||
      scale > MAX_SCALE
    ) {
      throw new TypeError("invalid Decimal parts");
    }
    this.negative = negative;
    this.mantissa = mantissa;
    this.scale = scale;
    Object.freeze(this);
  }

  /** The Decimal with these parts (a negative zero is kept). */
  static fromParts(negative, mantissa, scale) {
    return new Decimal(negative, mantissa, scale);
  }

  /**
   * Strict parse: `-?(0|[1-9][0-9]*)(\.[0-9]{1,28})?` whose digits fit in 96 bits; null
   * otherwise. Every accepted text gives the same value as rust_decimal's `from_str` (which
   * also reads "-0" as zero), and every text rust_decimal prints is accepted.
   */
  static parse(text) {
    if (typeof text !== "string") return null;
    const match = CANONICAL_DECIMAL.exec(text);
    if (match === null) return null;
    const fraction = match[3] ?? "";
    if (fraction.length > MAX_SCALE) return null;
    const mantissa = BigInt(match[2] + fraction);
    if (mantissa >= MANTISSA_LIMIT) return null;
    return new Decimal(match[1] === "-" && mantissa !== 0n, mantissa, fraction.length);
  }

  isZero() {
    return this.mantissa === 0n;
  }

  /** rust_decimal's Display: sign (also of zero), digits, "." and exactly `scale` decimals. */
  toString() {
    let digits = this.mantissa.toString();
    if (digits.length <= this.scale) digits = "0".repeat(this.scale - digits.length + 1) + digits;
    const point = digits.length - this.scale;
    const body = this.scale === 0 ? digits : `${digits.slice(0, point)}.${digits.slice(point)}`;
    return (this.negative ? "-" : "") + body;
  }
}

function signed(d) {
  return d.negative ? -d.mantissa : d.mantissa;
}

/** Half-to-even rounding of the non-negative `n / divisor`. */
function roundHalfEven(n, divisor) {
  const quotient = n / divisor;
  const twice = (n % divisor) * 2n;
  if (twice > divisor || (twice === divisor && quotient % 2n === 1n)) return quotient + 1n;
  return quotient;
}

/**
 * rust_decimal's checked add/sub: a zero operand returns the other one unchanged (negated for
 * `0 - x`, x nonzero); otherwise the exact result at the larger scale, a zero result being
 * positive; when its mantissa does not fit in 96 bits the scale is reduced by the fewest
 * digits that make it fit, rounding half to even; Overflow when even scale 0 does not fit.
 */
function addSub(a, b, subtract, what) {
  if (a.isZero()) {
    return subtract && !b.isZero() ? new Decimal(!b.negative, b.mantissa, b.scale) : b;
  }
  if (b.isZero()) return a;
  const scale = Math.max(a.scale, b.scale);
  const x = signed(a) * POW10[scale - a.scale];
  const y = signed(b) * POW10[scale - b.scale];
  const exact = subtract ? x - y : x + y;
  if (exact === 0n) return new Decimal(false, 0n, scale);
  const negative = exact < 0n;
  const magnitude = negative ? -exact : exact;
  for (let drop = 0; drop <= scale; drop++) {
    const mantissa = drop === 0 ? magnitude : roundHalfEven(magnitude, POW10[drop]);
    if (mantissa < MANTISSA_LIMIT) return new Decimal(negative, mantissa, scale - drop);
  }
  throw new BindError("Overflow", `decimal ${what} overflowed`);
}

/** a + b, or BindError("Overflow"). */
export function decimalAdd(a, b) {
  return addSub(a, b, false, "addition");
}

/** a - b, or BindError("Overflow"). */
export function decimalSub(a, b) {
  return addSub(a, b, true, "subtraction");
}

/** -a, as rust_decimal's `ZERO.checked_sub(a)`: a zero (of either sign) is returned unchanged. */
export function decimalNeg(a) {
  return addSub(new Decimal(false, 0n, 0), a, true, "negation");
}

/** -1, 0 or 1 by value (scale and the sign of zero are ignored), like rust_decimal's Ord. */
export function decimalCompare(a, b) {
  const scale = Math.max(a.scale, b.scale);
  const x = signed(a) * POW10[scale - a.scale];
  const y = signed(b) * POW10[scale - b.scale];
  return x < y ? -1 : x > y ? 1 : 0;
}

/** The text of a Decimal (rust_decimal's Display). */
export function displayDecimal(d) {
  return d.toString();
}

// ---------------------------------------------------------------------------------------------
// Double / Float
// ---------------------------------------------------------------------------------------------

/** Rounds to the nearest IEEE f32 (applied after every Float operation). */
export function f32(x) {
  return Math.fround(x);
}

/**
 * ECMAScript Number::toString(10), i.e. `String(x)`: the definition of DisplayDouble and
 * DisplayFloat that `js_number_to_string` in bindc and in the Rust runtime replicates.
 */
export function jsNumberToString(x) {
  return String(x);
}

// ---------------------------------------------------------------------------------------------
// Structural equality and order
// ---------------------------------------------------------------------------------------------

/** Structural equality: BigInt, numbers (IEEE ==), Decimal by value, null, arrays, records/variants. */
export function equals(a, b) {
  if (a === null || b === null) return a === b;
  if (typeof a !== "object") return a === b;
  if (a instanceof Decimal) return b instanceof Decimal && decimalCompare(a, b) === 0;
  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!equals(a[i], b[i])) return false;
    return true;
  }
  if (typeof b !== "object" || Array.isArray(b) || b instanceof Decimal) return false;
  const keys = Object.keys(a);
  if (keys.length !== Object.keys(b).length) return false;
  for (const key of keys) {
    if (!Object.hasOwn(b, key) || !equals(a[key], b[key])) return false;
  }
  return true;
}

function compareStrings(a, b) {
  // Code point order, like Rust's `str` order (UTF-16 code units differ above U+FFFF).
  const x = a[Symbol.iterator]();
  const y = b[Symbol.iterator]();
  for (;;) {
    const p = x.next();
    const q = y.next();
    if (p.done || q.done) return p.done === q.done ? 0 : p.done ? -1 : 1;
    const c = p.value.codePointAt(0);
    const d = q.value.codePointAt(0);
    if (c !== d) return c < d ? -1 : 1;
  }
}

/**
 * Structural order: -1, 0 or 1 (NaN when two numbers are unordered, so every `<`, `<=`, `>`,
 * `>=` against 0 is false, as for Rust's f64). null sorts before any value (Option order);
 * arrays and records compare element by element (records in field order); false < true.
 */
export function compare(a, b) {
  if (a === null || b === null) return a === b ? 0 : a === null ? -1 : 1;
  switch (typeof a) {
    case "bigint":
    case "number":
      return a < b ? -1 : a > b ? 1 : a === b ? 0 : NaN;
    case "boolean":
      return a === b ? 0 : a ? 1 : -1;
    case "string":
      return compareStrings(a, b);
    default:
      break;
  }
  if (a instanceof Decimal) return decimalCompare(a, b);
  const xs = Array.isArray(a) ? a : Object.values(a);
  const ys = Array.isArray(b) ? b : Object.values(b);
  const n = Math.min(xs.length, ys.length);
  for (let i = 0; i < n; i++) {
    const order = compare(xs[i], ys[i]);
    if (order !== 0) return order;
  }
  return xs.length === ys.length ? 0 : xs.length < ys.length ? -1 : 1;
}

// ---------------------------------------------------------------------------------------------
// Lists (frozen arrays)
// ---------------------------------------------------------------------------------------------

const EMPTY_LIST = Object.freeze([]);

export function emptyList() {
  return EMPTY_LIST;
}

/** A frozen list of the arguments (for long literals, generated code may pass an array to `listFrom`). */
export function listOf(...xs) {
  return Object.freeze(xs);
}

/** A frozen copy of an array. */
export function listFrom(array) {
  return Object.freeze(Array.from(array));
}

function optional(value, nested) {
  return nested ? Object.freeze({ some: value }) : value;
}

/**
 * The first element or null. When the element type is itself optional, pass `nested = true`:
 * the element is wrapped as {some: element} so an empty list (null) stays distinct.
 */
export function first(xs, nested = false) {
  return xs.length === 0 ? null : optional(xs[0], nested);
}

/** The element at BigInt index `i` or null (out of range or negative); `nested` as in `first`. */
export function get(xs, i, nested = false) {
  if (i < 0n || i >= BigInt(xs.length)) return null;
  return optional(xs[Number(i)], nested);
}

export function length(xs) {
  return BigInt(xs.length);
}

/** Applies the async `f(ctx, x)` to each element in order (a loop, no recursion). */
export async function map(ctx, xs, f) {
  const out = [];
  for (const x of xs) out.push(await f(ctx, x));
  return Object.freeze(out);
}

/** Folds with the async `f(ctx, acc, x)` from the left (a loop, no recursion). */
export async function fold(ctx, xs, init, f) {
  let acc = init;
  for (const x of xs) acc = await f(ctx, acc, x);
  return acc;
}

// ---------------------------------------------------------------------------------------------
// Records and variants (no prototype pollution)
// ---------------------------------------------------------------------------------------------

/**
 * A frozen null-prototype object from [name, value] pairs, defined with
 * Object.defineProperty (so names such as "__proto__" or "constructor" are plain fields).
 */
export function record(entries) {
  const object = Object.create(null);
  for (const [name, value] of entries) {
    Object.defineProperty(object, name, { value, enumerable: true, writable: false, configurable: false });
  }
  return Object.freeze(object);
}

/** A variant value: record([["tag", tag], ...entries]). */
export function variant(tag, entries) {
  return record([["tag", tag], ...entries]);
}

// ---------------------------------------------------------------------------------------------
// Decoders (JSON -> values). Protocol: a decoder is a synchronous function `(json) => value`
// that throws DecodeError on malformed input; `decoder.optional === true` marks a decoder
// that accepts null (a missing record field is then read as null, as the server does).
// ---------------------------------------------------------------------------------------------

function fail(what) {
  throw new DecodeError(`expected ${what}`);
}

function isPlainObject(json) {
  return typeof json === "object" && json !== null && !Array.isArray(json);
}

export function decodeString(json) {
  return typeof json === "string" ? json : fail("a string");
}

export function decodeBool(json) {
  return typeof json === "boolean" ? json : fail("a boolean");
}

/** Int: a canonical integer string. */
export function decodeInt(json) {
  const value = intParse(json);
  return value === null ? fail("a canonical integer string") : value;
}

/** Decimal / Money: a decimal string (Decimal.parse). */
export function decodeDecimal(json) {
  const value = Decimal.parse(json);
  return value === null ? fail("a decimal string") : value;
}

export function decodeDouble(json) {
  return typeof json === "number" ? json : fail("a number");
}

/** Float: a number that is exactly an f32. */
export function decodeFloat(json) {
  return typeof json === "number" && Math.fround(json) === json ? json : fail("an f32 number");
}

/** T?: null, or the inner decoder's value. */
export function decodeOptional(inner) {
  const decoder = (json) => (json === null ? null : inner(json));
  decoder.optional = true;
  return decoder;
}

/** List<T>: an array, decoded item by item into a frozen array. */
export function decodeList(item) {
  return (json) => {
    if (!Array.isArray(json)) fail("an array");
    const out = [];
    for (const value of json) out.push(item(value));
    return Object.freeze(out);
  };
}

function fieldMap(fields) {
  return new Map(fields);
}

function decodeFields(fields, json, prefix) {
  if (!isPlainObject(json)) fail("an object");
  for (const key of Object.keys(json)) {
    if (!fields.has(key)) fail(`no field ${JSON.stringify(key)}`);
  }
  const entries = [...prefix];
  for (const [name, decoder] of fields) {
    if (Object.hasOwn(json, name)) entries.push([name, decoder(json[name])]);
    else if (decoder.optional === true) entries.push([name, null]);
    else fail(`field ${JSON.stringify(name)}`);
  }
  return record(entries);
}

/**
 * A record decoder from [name, decoder] pairs: the JSON must be an object with exactly these
 * fields (unknown fields rejected; a missing field is null when its decoder is optional);
 * gives record(...) with the fields in the given order.
 */
export function decodeRecord(fields) {
  const map = fieldMap(fields);
  return (json) => decodeFields(map, json, []);
}

/**
 * A sum type decoder in serde's externally tagged form: cases are [wireName, tag, fields],
 * `fields` null for a unit variant (JSON: the string wireName) or [name, decoder] pairs
 * (JSON: {wireName: {fields}}). Gives variant(tag, fields).
 */
export function decodeVariant(cases) {
  const byName = new Map(cases.map(([wire, tag, fields]) => [wire, { tag, fields: fields === null ? null : fieldMap(fields) }]));
  return (json) => {
    if (typeof json === "string") {
      const found = byName.get(json);
      if (found === undefined || found.fields !== null) fail("a variant");
      return variant(found.tag, []);
    }
    if (!isPlainObject(json)) fail("a variant");
    const keys = Object.keys(json);
    if (keys.length !== 1) fail("a variant");
    const found = byName.get(keys[0]);
    if (found === undefined || found.fields === null) fail("a variant");
    return decodeFields(found.fields, json[keys[0]], [["tag", found.tag]]);
  };
}

/** Result<T, E> in serde's form {"Ok": v} / {"Err": e}: gives variant("Ok" | "Err", [["value", v]]). */
export function decodeResult(ok, err) {
  return (json) => {
    if (!isPlainObject(json)) fail("a result");
    const keys = Object.keys(json);
    if (keys.length !== 1) fail("a result");
    if (keys[0] === "Ok") return variant("Ok", [["value", ok(json.Ok)]]);
    if (keys[0] === "Err") return variant("Err", [["value", err(json.Err)]]);
    return fail("a result");
  };
}

// ---------------------------------------------------------------------------------------------
// Server calls and URL parameters
// ---------------------------------------------------------------------------------------------

function requestFailed() {
  return new BindError("Remote", TEXTS.requestFailed);
}

/**
 * POSTs `body` (a JSON-ready value produced by the generated encoders: no BigInt or Decimal
 * left) to `url` with the global `fetch` and decodes the 2xx JSON response with `decode`.
 * A non-2xx response whose body is JSON `{"error": string}` gives BindError("Remote", that
 * string); a network error, a body that is not JSON (any status), any other error body or a
 * decode failure gives BindError("Remote", TEXTS.requestFailed). Not counted by `enter`.
 */
export async function rpc(ctx, url, body, decode) {
  let text;
  let response;
  try {
    response = await fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json", accept: "application/json" },
      body: JSON.stringify(body),
    });
    text = await response.text();
  } catch {
    throw requestFailed();
  }
  let json;
  try {
    json = JSON.parse(text);
  } catch {
    throw requestFailed();
  }
  if (!response.ok) {
    if (isPlainObject(json) && Object.hasOwn(json, "error") && typeof json.error === "string") {
      throw new BindError("Remote", json.error);
    }
    throw requestFailed();
  }
  try {
    return decode(json);
  } catch {
    throw requestFailed();
  }
}

/** Text decoders for URL parameters: `(string) => value`, throwing DecodeError when invalid. */
export function textString(text) {
  return text;
}

export function textInt(text) {
  return decodeInt(text);
}

export function textDecimal(text) {
  return decodeDecimal(text);
}

export function textBool(text) {
  if (text === "true") return true;
  if (text === "false") return false;
  return fail("true or false");
}

/**
 * Reads the parameters `specs` ([name, textDecoder] pairs) from a query string with
 * URLSearchParams semantics (percent-decoding, "+" is a space). A parameter that is absent,
 * repeated or rejected by its decoder gives BindError("BadParameter", name); unknown
 * parameters are ignored. Gives record(...) with the parameters in the given order.
 */
export function readParams(search, specs) {
  const params = new URLSearchParams(search);
  const entries = [];
  for (const [name, decoder] of specs) {
    const values = params.getAll(name);
    if (values.length !== 1) throw new BindError("BadParameter", name);
    try {
      entries.push([name, decoder(values[0])]);
    } catch {
      throw new BindError("BadParameter", name);
    }
  }
  return record(entries);
}

// ---------------------------------------------------------------------------------------------
// UI nodes and rendering (same HTML as the Rust runtime's render_html)
// ---------------------------------------------------------------------------------------------

/** Bind node name -> HTML element of the container nodes. */
const CONTAINERS = new Map([
  ["Page", "div"], ["Container", "div"], ["Div", "div"], ["Grid", "div"], ["Stack", "div"],
  ["Header", "header"], ["Nav", "nav"], ["Main", "main"], ["Section", "section"],
  ["Article", "article"], ["Aside", "aside"], ["Footer", "footer"], ["Paragraph", "p"],
  ["Span", "span"], ["Strong", "strong"], ["Emphasis", "em"], ["Small", "small"],
  ["List", "ul"], ["Item", "li"], ["Pre", "pre"], ["Code", "code"],
]);
const SPECIAL = new Set(["UI", "Heading", "Link", "Rule"]);

/**
 * A UI element: `tag` is the Bind node name ("UI" for the root, "Div", "Heading", "Link", ...),
 * `args` its arguments (strings or BigInts), `children` UI nodes. Frozen.
 */
export function node(tag, args, children) {
  if (!CONTAINERS.has(tag) && !SPECIAL.has(tag)) throw new TypeError(`unknown UI node ${tag}`);
  return Object.freeze({ kind: "element", tag, args: Object.freeze([...args]), children: Object.freeze([...children]) });
}

/** A text node (escaped when rendered, never parsed as HTML). */
export function text(s) {
  return Object.freeze({ kind: "text", text: s });
}

/** The empty node (renders nothing). */
export const EMPTY = Object.freeze({ kind: "empty" });

function argText(arg) {
  return typeof arg === "bigint" ? arg.toString() : arg;
}

function headingLevel(arg) {
  if (typeof arg !== "bigint") return 1;
  return arg < 1n ? 1 : arg > 6n ? 6 : Number(arg);
}

/**
 * Whether a link's href may be emitted as is (Rust's `is_allowed_href`): after trimming
 * characters <= U+0020 at both ends and removing tab, LF and CR anywhere, a URL with a scheme
 * (`^[A-Za-z][A-Za-z0-9+.-]*:` before any other character) is allowed only for http, https,
 * mailto and tel (ASCII case-insensitive); a URL without a scheme is allowed.
 */
function isAllowedHref(url) {
  const chars = [...url];
  let start = 0;
  let end = chars.length;
  while (start < end && chars[start].codePointAt(0) <= 0x20) start++;
  while (end > start && chars[end - 1].codePointAt(0) <= 0x20) end--;
  const normalized = chars.slice(start, end).filter((c) => c !== "\t" && c !== "\n" && c !== "\r");
  if (normalized.length === 0 || !/^[A-Za-z]$/.test(normalized[0])) return true;
  let scheme = normalized[0];
  for (const c of normalized.slice(1)) {
    if (c === ":") return ["http", "https", "mailto", "tel"].includes(scheme.toLowerCase());
    if (/^[A-Za-z0-9+.-]$/.test(c)) scheme += c;
    else return true;
  }
  return true;
}

function renderInto(out, value, document) {
  if (value.kind === "empty") return;
  if (value.kind === "text") {
    out.push(document.createTextNode(value.text));
    return;
  }
  const { tag, args, children } = value;
  if (tag === "UI") {
    for (const child of children) renderInto(out, child, document);
    return;
  }
  const arg = (index) => (index < args.length ? argText(args[index]) : undefined);
  const attributes = [];
  const push = (name, attribute) => {
    if (attribute !== undefined) attributes.push([name, attribute]);
  };
  let elementName;
  let renderChildren = true;
  if (tag === "Heading") {
    elementName = `h${headingLevel(args[0])}`;
    push("class", arg(1));
  } else if (tag === "Link") {
    const href = arg(0);
    push("href", href === undefined ? undefined : isAllowedHref(href) ? href : "");
    push("class", arg(1));
    const target = arg(2);
    push("target", target);
    if (target === "_blank") push("rel", "noopener noreferrer");
    push("aria-label", arg(3));
    elementName = "a";
  } else if (tag === "Rule") {
    elementName = "hr";
    push("class", arg(0));
    renderChildren = false;
  } else {
    elementName = CONTAINERS.get(tag);
    push("class", arg(0));
    push("id", arg(1));
  }
  const element = document.createElement(elementName);
  for (const [name, attribute] of attributes) element.setAttribute(name, attribute);
  if (renderChildren) {
    const nodes = [];
    for (const child of children) renderInto(nodes, child, document);
    for (const child of nodes) element.appendChild(child);
  }
  out.push(element);
}

/**
 * The DOM nodes of a UI value, built with document.createElement / createTextNode /
 * setAttribute / appendChild only: an array, since the "UI" root is a fragment and EMPTY is
 * nothing (mount with `container.replaceChildren(...render(tree, document))`). Serialized with
 * the canonical escaping they equal the Rust runtime's render_html.
 */
export function render(value, document) {
  const out = [];
  renderInto(out, value, document);
  return out;
}

// ---------------------------------------------------------------------------------------------
// Page shell and error screen (same markup as the Rust runtime)
// ---------------------------------------------------------------------------------------------

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
}

/** Rust's page_html: the full document; title and stylesheet escaped, `body` (HTML) as is. */
export function pageHtml(title, stylesheet, body) {
  return (
    '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width, initial-scale=1">' +
    `<title>${escapeHtml(title)}</title><link rel="stylesheet" href="${escapeHtml(stylesheet)}"></head>` +
    `<body><div class="bind-site">${body}</div></body></html>`
  );
}

/**
 * Rust's error_body as a UI tree: { status, tree } where tree renders to
 * `<main class="bind-error"><h1>title</h1><p>public message</p></main>`. `kind` is an
 * AppError kind: "BadRequest" (message shown), "NotFound", "Internal", "Overflow",
 * "RecursionLimit" (fixed public messages, the given message is never shown).
 */
export function errorBody(kind, message) {
  let status = 500;
  let publicMessage;
  switch (kind) {
    case "BadRequest":
      status = 400;
      publicMessage = message;
      break;
    case "NotFound":
      status = 404;
      publicMessage = "not found";
      break;
    case "Overflow":
      publicMessage = "numeric overflow";
      break;
    case "RecursionLimit":
      publicMessage = "recursion limit exceeded";
      break;
    default:
      publicMessage = "internal error";
  }
  const title = status === 400 ? TEXTS.titleBadRequest : status === 404 ? TEXTS.titleNotFound : TEXTS.titleError;
  const tree = node("Main", ["bind-error"], [node("Heading", [1n], [text(title)]), node("Paragraph", [], [text(publicMessage)])]);
  return Object.freeze({ status, tree });
}
